namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage1; use kuaiyun\URLRequest; use Exception; class kuaiyun extends cloudStorage1 { var $access_key; var $secret_key; var $voucher; var $resource; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_kuaiyun_custom_upload_dir; $this->protocol = $this->options->cloud_storage_kuaiyun_protocol; $this->host = $this->options->cloud_storage_kuaiyun_host; $this->folder = $this->options->cloud_storage_kuaiyun_folder; $this->access_key = trim($this->options->cloud_storage_kuaiyun_access_key); $this->secret_key = trim($this->options->cloud_storage_kuaiyun_secret_key); $this->voucher = trim($this->options->cloud_storage_kuaiyun_voucher); $this->resource = trim($this->options->cloud_storage_kuaiyun_resource); $this->bucket = trim($this->options->cloud_storage_kuaiyun_bucket); $this->cloud_thumbnail = false; $this->silent_scanning = $this->options->cloud_storage_kuaiyun_silent_scanning; $this->auto_replace = $this->options->cloud_storage_kuaiyun_auto_replace; $this->sync_delete = $this->options->cloud_storage_kuaiyun_sync_delete; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_kuaiyun_delete_attachment_after_synced; $this->sync_the_website_resource = $this->options->cloud_storage_kuaiyun_sync_the_website_resource; $this->website_resource_filetypes = $this->options->cloud_storage_kuaiyun_website_resource_filetypes; $this->custom_replacement = $this->options->cloud_storage_kuaiyun_custom_replacement; add_filter( 'qqworld-collector-cloud-storage-settings', array($this, 'cloud_storage_settings') ); } public function cloud_storage_settings($values) { if (isset($values[$this->guid])) { $GLOBALS['QC']->cache->delete_cache('kuaiyun-token'); } return $values; } public function includes() { if ( !function_exists('kuaiyun\URLRequest') ) { require QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'sdk' . DIRECTORY_SEPARATOR . 'kuaiyun' . DIRECTORY_SEPARATOR . 'sdk.php'; } } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { $this->includes(); $this->accessed = $this->get_option_token(); } } public function get_option_token() { $now = time(); $token = $GLOBALS['QC']->cache->get_cache('kuaiyun-token'); if (!$token) { try { $token = $this->get_token($this->voucher, $this->access_key, $this->secret_key, $this->resource); if ($token) $GLOBALS['QC']->cache->set_cache('kuaiyun-token', $token, 86400); } catch ( Exception $e ) { if ($e->getMessage()) print '<div class="error"><p>' . $e->getMessage() . '</p></div>'; } } return $token; } public function get_token($voucher, $accessKey, $secretKey, $resource){ $url = "http://api.storagesdk.com/restful/storageapi/storage/getToken"; $query = array(); $data = array(); $data["voucher"]= $voucher; $data["accessKey"]= $accessKey ; $data["secretKey"]= $secretKey; $data["resource"]= $resource; $body = json_encode($data, JSON_INVALID_UTF8_IGNORE); $headers = array( 'Content-Type' => 'application/json; charset=utf-8', );; $request = new URLRequest($url, $headers, $query, "json", true, $body, '5'); $response = $request->exec(); $msg = json_decode($response,true)["message"]; $arr = explode(":",$msg); if (isset($arr[1])) { $token = $arr[1]; } else { $token = false; throw new Exception($arr[0]); } return $token; } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); $url = "http://api.storagesdk.com/restful/storageapi/file/getFileUrl"; $minutes = 0; $token = $this->get_option_token(); $query = array(); $data = array(); $data["token"] = $token; $data["resource"] =$this->resource; $data["fileName"] = $destination_path; $data["bucketName"] = $this->bucket; $data["minutes"] = $minutes; $body = json_encode($data, JSON_INVALID_UTF8_IGNORE); $headers = array("Content-Type: application/json; charset=utf-8"); $request = new URLRequest($url, $headers, $query, "json", true, $body); $response = $request->exec(); $result = json_decode($response,true); return !$result['code'] ? $result["message"] : false; } public function upload($destination_path, $source_path) { $this->access_service(); if (!file_exists($source_path) || !filesize($source_path)) return false; if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } set_time_limit($this->options->qc_stress_timeout); $url = "http://api.storagesdk.com/restful/storageapi/file/uploadFile"; $token = $this->get_option_token(); $data = array(); $data['input'] = file_get_contents($source_path); $file = base64_encode($destination_path); $length = strlen($data['input']); $headers = array( 'Content-Type' => 'application/json;charset=utf-8', 'token' => $token, 'fileName' => $file, 'bucketName' => $this->bucket, 'resource' => $this->resource, 'length' => $length, ); $body = $data["input"]; $request = new URLRequest($url, $headers, $data, "json", true, $body); $response = $request->exec(); $result = json_decode($response,true); if ($result['code']) { do_action( 'qqworld-collector-log', $this->log_id, 'KuaiYun Upload File ($err):', print_r($result['message'], true) ); return false; } return !$result['code']; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); $url = "http://api.storagesdk.com/restful/storageapi/file/deleteFile"; $token = $this->get_option_token(); $query = array(); $data = array(); $data["token"] = $token; $data["fileName"] = $object; $data["bucketName"] = $this->bucket; $data["resource"] = $this->resource; $body = json_encode($data, JSON_INVALID_UTF8_IGNORE); $headers = array( 'Content-Type' => 'application/json; charset=utf-8', ); $request = new URLRequest($url, $headers, $query, "json", true, $body); $response = $request->exec(); $result = json_decode($response, true); if ($result['code']) { do_action( 'qqworld-collector-log', $this->log_id, 'KuaiYun Delete File ($err):', print_r($result['message'], true) ); return false; } return !$result['code']; } } ?>